<?php
declare(strict_types=1);
require_once __DIR__ . '/config/product_step12.php';
$error=null;$quotes=[];$selected=null;$items=[];$id=isset($_GET['id'])&&is_numeric($_GET['id'])?(int)$_GET['id']:0;
try{
    $pdo=business_db();product_step12_ensure($pdo);$ctx=product_org_context($pdo);$orgId=(int)$ctx['organization_id'];
    $stmt=$pdo->prepare("SELECT q.*,m.market_name,m.currency_code,l.order_id FROM product_quotes q JOIN product_markets m ON m.id=q.market_id LEFT JOIN product_quote_order_links l ON l.organization_id=q.organization_id AND l.quote_id=q.id WHERE q.organization_id=? ORDER BY q.id DESC LIMIT 100");
    $stmt->execute([$orgId]);$quotes=$stmt->fetchAll();
    if($id>0){
        $stmt=$pdo->prepare("SELECT q.*,m.market_name,m.currency_code,l.order_id FROM product_quotes q JOIN product_markets m ON m.id=q.market_id LEFT JOIN product_quote_order_links l ON l.organization_id=q.organization_id AND l.quote_id=q.id WHERE q.organization_id=? AND q.id=? LIMIT 1");
        $stmt->execute([$orgId,$id]);$selected=$stmt->fetch()?:null;if(!$selected)throw new RuntimeException('Saved quote was not found.');
        $stmt=$pdo->prepare("SELECT * FROM product_quote_items WHERE quote_id=? ORDER BY id");$stmt->execute([$id]);$items=$stmt->fetchAll();
    }
}catch(Throwable $e){$error=$e->getMessage();}
?>
