<div style="max-width:460px;margin:16px 0 0 auto"><div class="pp-total"><span>MRP Total</span><strong>₹<?= number_format((float)$selected['subtotal_mrp'],2) ?></strong></div><div class="pp-total"><span>Payable</span><strong>₹<?= number_format((float)$selected['payable_amount'],2) ?></strong></div><div class="pp-total"><span>Saving</span><strong>₹<?= number_format((float)$selected['saving_amount'],2) ?></strong></div><div class="pp-total"><span>Total VP</span><strong><?= product_h($selected['total_vp']) ?></strong></div><div class="pp-total"><span>Delivery</span><strong>₹<?= number_format((float)$selected['delivery_charge'],2) ?></strong></div><div class="pp-total pp-grand"><span>Grand Total</span><strong>₹<?= number_format((float)$selected['grand_total'],2) ?></strong></div></div><?php if($selected['notes']):?><div class="os-footer-note"><strong>Notes:</strong> <?= product_h($selected['notes']) ?></div><?php endif;?></section>
<?php else:?><section class="os-card" style="margin-top:14px"><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Quote</th><th>Customer</th><th>Tier</th><th>MRP</th><th>Payable</th><th>VP</th><th>Grand Total</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($quotes as $q):?><tr><td><b><?= product_h($q['quote_code']) ?></b><small><?= product_h($q['created_at']) ?></small></td><td><?= product_h($q['customer_name']?:'—') ?></td><td><?= product_h($q['pricing_tier_code']) ?></td><td>₹<?= number_format((float)$q['subtotal_mrp'],2) ?></td><td>₹<?= number_format((float)$q['payable_amount'],2) ?></td><td><?= product_h($q['total_vp']) ?></td><td>₹<?= number_format((float)$q['grand_total'],2) ?></td><td><span class="pp-badge"><?= $q['order_id']?'ORDER #'.(int)$q['order_id']:strtoupper((string)$q['status']) ?></span></td><td><a class="pp-badge" href="?id=<?= (int)$q['id'] ?>">Open</a></td></tr><?php endforeach;?></tbody></table></div><?php if(!$quotes):?><div class="pp-empty">No saved quotes yet. Build one in Order Builder.</div><?php endif;?></section><?php endif;?></main></div><script src="assets/business-collapsible.js?v=20260820-1" defer></script></body></html>
